          if (f.jumpPending) {
            f.bufferedRelease = { remaining: t.jumpBufferSeconds, x: input.x, charge: f.charge };
            f.jumpPending = false; f.charging = false; f.charge = 0; f.holdTime = 0;
          }
          this.detach(f);
        }
        f.held = input.held;
      }
